CREATE DATABASE library_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE library_demo;
CREATE TABLE book_copies(id INT PRIMARY KEY,title VARCHAR(80) NOT NULL,available INT NOT NULL DEFAULT 1,CHECK(available IN(0,1))) ENGINE=InnoDB;
CREATE TABLE readers(id INT PRIMARY KEY,name VARCHAR(40) NOT NULL) ENGINE=InnoDB;
CREATE TABLE loans(id INT PRIMARY KEY,copy_id INT NOT NULL,reader_id INT NOT NULL,borrowed_at DATETIME NOT NULL,returned_at DATETIME NULL,FOREIGN KEY(copy_id) REFERENCES book_copies(id),FOREIGN KEY(reader_id) REFERENCES readers(id)) ENGINE=InnoDB;
INSERT INTO book_copies VALUES(12,'数据库起点',1),(13,'SQL练习',1);
INSERT INTO readers VALUES(7,'小林');

USE library_demo;
UPDATE book_copies SET title='SQL练习·修订版' WHERE id=13;
SELECT id,title,available FROM book_copies ORDER BY id;

USE library_demo;
INSERT INTO readers VALUES(8,'阿禾');
UPDATE readers SET name='阿禾同学' WHERE id=8;
SELECT id,name FROM readers WHERE id IN(7,8) ORDER BY id;

USE library_demo;
CREATE SQL SECURITY INVOKER VIEW open_loans AS
SELECT l.id AS loan_id,b.title,r.name,l.borrowed_at
FROM loans l JOIN book_copies b ON l.copy_id=b.id
JOIN readers r ON l.reader_id=r.id
WHERE l.returned_at IS NULL;
SELECT loan_id,title,name FROM open_loans ORDER BY loan_id;

CREATE DATABASE shop_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE shop_demo;
CREATE TABLE shop_products(id INT PRIMARY KEY,title VARCHAR(80) NOT NULL,stock INT NOT NULL CHECK(stock>=0),price_cents INT NOT NULL CHECK(price_cents>=0)) ENGINE=InnoDB;
CREATE TABLE shop_orders(id INT PRIMARY KEY,product_id INT NOT NULL,qty INT NOT NULL CHECK(qty>0),unit_price_cents INT NOT NULL CHECK(unit_price_cents>=0),total_cents BIGINT NOT NULL CHECK(total_cents>=0),status VARCHAR(16) NOT NULL,FOREIGN KEY(product_id) REFERENCES shop_products(id)) ENGINE=InnoDB;
INSERT INTO shop_products VALUES(11,'练习册',5,1200);
